/* ========================= GEOMETRÍA ========================= */

function normalizeAngle(angle) {
    while (angle > 180) angle -= 360;
    while (angle <= -180) angle += 360;
    return angle;
}

function getVisualSector(angle) {
    // Sector 8 cruza el límite +180/-180.
    if (angle >= 198 || angle < -126) {
        return 8;
    }

    const sector = WHEEL.sectors.find(
        item => angle >= item.start && angle < item.end
    );

    return sector ? sector.number : 8;
}

function classifyPoint(x, y) {
    const dx = x - FIGURE.centerX;
    const dy = y - FIGURE.centerY;

    const distance = Math.hypot(dx, dy);

    // Centro real de la figura.
    if (distance <= FIGURE.centerRadius) {
        return {
            center: true,
            visualSector: 0,
            diagnosticSector: 0
        };
    }

    let angle = Math.atan2(dy, dx) * 180 / Math.PI;
    angle = normalizeAngle(angle);

    const visualSector = getVisualSector(angle);

    const diagnosticSector =
        hand === "zurdo"
            ? LEFT_HAND_MAP[visualSector]
            : visualSector;

    return {
        center: false,
        visualSector,
        diagnosticSector
    };
}

/* ========================= COORDENADAS ========================= */

function getImageCoordinates(event) {
    const rect = target.getBoundingClientRect();

    return {
        x: ((event.clientX - rect.left) / rect.width) * FIGURE.width,
        y: ((event.clientY - rect.top) / rect.height) * FIGURE.height
    };
}

/* ========================= REGISTRAR DISPARO ========================= */

function findShotAt(x, y) {
    const radius = 38;
    let found = null;
    let best = Infinity;

    shots.forEach(shot => {
        const d = Math.hypot(shot.x - x, shot.y - y);
        if (d <= radius && d < best) {
            found = shot;
            best = d;
        }
    });

    return found;
}

/* ================= INTERACCIÓN TÁCTIL SEGURA =================
   Toque corto = impacto.
   Deslizamiento = scroll, NO impacto.
   En edición: tocar + arrastrar = mover impacto.
============================================================== */

let pointerStart = null;
let pointerMoved = false;
let activePointerId = null;
const TAP_TOLERANCE = 12;

target.addEventListener("pointerdown", event => {
    if (event.isPrimary === false) return;

    activePointerId = event.pointerId;
    pointerStart = { x: event.clientX, y: event.clientY };
    pointerMoved = false;

    if (editMode) {
        const point = getImageCoordinates(event);
        const hit = findShotAt(point.x, point.y);

        if (hit) {
            selectedShotId = hit.id;
            draggingShotId = hit.id;
            target.setPointerCapture?.(event.pointerId);
            event.preventDefault();
            drawShots();
        }
    }
});

target.addEventListener("pointermove", event => {
    if (event.pointerId !== activePointerId || !pointerStart) return;

    const dx = event.clientX - pointerStart.x;
    const dy = event.clientY - pointerStart.y;

    if (Math.hypot(dx, dy) > TAP_TOLERANCE) {
        pointerMoved = true;
    }

    if (!editMode || draggingShotId === null) return;

    event.preventDefault();

    const shot = shots.find(item => item.id === draggingShotId);
    if (!shot) return;

    const point = getImageCoordinates(event);
    const classification = classifyPoint(point.x, point.y);

    Object.assign(shot, {
        x: point.x,
        y: point.y,
        center: classification.center,
        visualSector: classification.visualSector,
        diagnosticSector: classification.diagnosticSector
    });

    drawShots();
});

target.addEventListener("pointerup", event => {
    if (event.pointerId !== activePointerId) return;

    if (!editMode && !pointerMoved) {
        const point = getImageCoordinates(event);
        const classification = classifyPoint(point.x, point.y);

        shots.push({
            id: shots.length + 1,
            x: point.x,
            y: point.y,
            center: classification.center,
            visualSector: classification.visualSector,
            diagnosticSector: classification.diagnosticSector
        });

        updateUI();
    }

    if (editMode && draggingShotId !== null) {
        draggingShotId = null;
        try { target.releasePointerCapture?.(event.pointerId); } catch (_) {}
        updateUI();
    }

    pointerStart = null;
    pointerMoved = false;
    activePointerId = null;
});

target.addEventListener("pointercancel", event => {
    if (event.pointerId !== activePointerId) return;

    draggingShotId = null;
    pointerStart = null;
    pointerMoved = false;
    activePointerId = null;

    try { target.releasePointerCapture?.(event.pointerId); } catch (_) {}
});

target.addEventListener("contextmenu", event => event.preventDefault());

/* ========================= DIBUJAR IMPACTOS ========================= */


/* ================= GUÍA DE SECTORES ================= */

let sectorsVisible = false;

function polarToCartesian(cx, cy, radius, angleDeg) {
    const angle = (angleDeg - 90) * Math.PI / 180;

    return {
        x: cx + radius * Math.cos(angle),
        y: cy + radius * Math.sin(angle)
    };
}

function describeWedge(startAngle, endAngle, radius) {
    const start = polarToCartesian(
        FIGURE.centerX,
        FIGURE.centerY,
        radius,
        startAngle
    );

    const end = polarToCartesian(
        FIGURE.centerX,
        FIGURE.centerY,
        radius,
        endAngle
    );

    const largeArcFlag =
        Math.abs(endAngle - startAngle) > 180 ? 1 : 0;

    return [
        `M ${FIGURE.centerX} ${FIGURE.centerY}`,
        `L ${start.x} ${start.y}`,
        `A ${radius} ${radius} 0 ${largeArcFlag} 1 ${end.x} ${end.y}`,
        "Z"
    ].join(" ");
}

function createSvgElement(name, attributes = {}) {
    const element = document.createElementNS(
        "http://www.w3.org/2000/svg",
        name
    );

    Object.entries(attributes).forEach(([key, value]) => {
        element.setAttribute(key, value);
    });

    return element;
}

function buildSectorGuide() {
    const guide = createSvgElement("g", {
        class: "sector-guide",
        "aria-hidden": "true"
    });

    // La guía utiliza la misma geometría que la clasificación de impactos.
    const radius = 430;

    WHEEL.sectors.forEach(sector => {
        const start = sector.start + 90;
        const end = sector.end + 90;

        const wedge = createSvgElement("path", {
            d: describeWedge(start, end, radius),
            class: "sector-guide__wedge"
        });

        guide.appendChild(wedge);

        const middle = (sector.start + sector.end) / 2;
        const labelRadius = 315;

        const labelPoint = polarToCartesian(
            FIGURE.centerX,
            FIGURE.centerY,
            labelRadius,
            middle + 90
        );

        const label = createSvgElement("text", {
            x: labelPoint.x,
            y: labelPoint.y,
            class: "sector-guide__label"
        });

        label.textContent = sector.number;
        guide.appendChild(label);
    });

    const center = createSvgElement("circle", {
        cx: FIGURE.centerX,
        cy: FIGURE.centerY,
        r: FIGURE.centerRadius,
        class: "sector-guide__center"
    });

    guide.appendChild(center);

    overlay.prepend(guide);
}

function setSectorsVisible(visible) {
    sectorsVisible = visible;

    toggleSectors.setAttribute(
        "aria-pressed",
        String(visible)
    );

    toggleSectorsText.textContent =
        visible ? "Ocultar sectores" : "Ver sectores";

    // La guía se actualiza inmediatamente, incluso cuando
    // todavía no existe ningún impacto registrado.
    drawShots();
}

toggleSectors.addEventListener("click", () => {
    setSectorsVisible(!sectorsVisible);
});

function drawShots() {
    overlay.innerHTML = "";

    if (sectorsVisible) {
        buildSectorGuide();
        const guide=overlay.querySelector(".sector-guide");
        if(guide) guide.classList.add("is-visible");
    }

    shots.forEach(shot=>{
        const group=document.createElementNS("http://www.w3.org/2000/svg","g");

        if(editMode){
            const hit=document.createElementNS("http://www.w3.org/2000/svg","circle");
            hit.setAttribute("cx",shot.x); hit.setAttribute("cy",shot.y); hit.setAttribute("r",34);
            hit.setAttribute("class","impact-hit-area"); group.appendChild(hit);
        }

        const circle=document.createElementNS("http://www.w3.org/2000/svg","circle");
        circle.setAttribute("cx",shot.x); circle.setAttribute("cy",shot.y); circle.setAttribute("r",17);
        circle.setAttribute("class","impact-circle"+(selectedShotId===shot.id?" is-selected":""));

        const text=document.createElementNS("http://www.w3.org/2000/svg","text");
        text.setAttribute("x",shot.x); text.setAttribute("y",shot.y); text.setAttribute("class","impact-number"); text.textContent=shot.id;

        group.append(circle,text); overlay.appendChild(group);
    });
}

/* ========================= UI ========================= */

function updateUI() {
    contador.textContent = shots.length;
    manoActual.textContent = hand.toUpperCase();

    const hasShots = shots.length > 0;

    undoButton.disabled = !hasShots;
    clearButton.disabled = !hasShots;
    diagnosticButton.disabled = !hasShots;
    reportButton.disabled = !hasShots;
    editPanel.hidden = !hasShots;
    if(!hasShots && editMode){ editMode=false; selectedShotId=null; draggingShotId=null; target.classList.remove("is-editing"); }
    drawShots();
}

/* ========================= DIESTRO / ZURDO ========================= */

handButtons.forEach(button => {
    button.addEventListener("click", () => {
        hand = button.dataset.hand;

        handButtons.forEach(item => {
            item.classList.toggle(
                "hand-button--active",
                item === button
            );
        });

        // Se conserva la ubicación física del impacto.
        // Solo cambia su interpretación diagnóstica.
        shots.forEach(shot => {
            shot.diagnosticSector = shot.center
                ? 0
                : hand === "zurdo"
                    ? LEFT_HAND_MAP[shot.visualSector]
                    : shot.visualSector;
        });

        updateUI();
    });
});

/* ========================= DESHACER ========================= */

undoButton.addEventListener("click", () => {
    if (!shots.length) return;

    shots.pop();

    shots.forEach((shot, index) => {
        shot.id = index + 1;
    });

    updateUI();
});

